//! Logical keys after keyboard-layout and modifier resolution.

use super::Physical;
use crate::SmolStr;

/// A logical key produced by the active keyboard layout.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Key<C = SmolStr> {
    /// A standardized non-text key.
    Named(Named),
    /// Text generated by the key under the current layout.
    Character(C),
    /// A key whose logical meaning is unavailable.
    Unidentified,
}

impl Key {
    /// Borrows character storage while preserving the key category.
    #[inline]
    pub fn as_ref(&self) -> Key<&str> {
        match self {
            Self::Named(key) => Key::Named(*key),
            Self::Character(text) => Key::Character(text.as_ref()),
            Self::Unidentified => Key::Unidentified,
        }
    }

    /// Resolves a character to a Latin-layout label when possible.
    pub fn to_latin(&self, physical: Physical) -> Option<char> {
        let Self::Character(text) = self else {
            return None;
        };
        let mut characters = text.chars();
        let character = characters.next()?;

        if characters.next().is_none() && character < '\u{370}' {
            return Some(character);
        }

        match physical {
            Physical::Code(code) => code.latin_label(),
            Physical::Unidentified(_) => None,
        }
    }
}

impl From<Named> for Key {
    #[inline]
    fn from(key: Named) -> Self {
        Self::Named(key)
    }
}

